import React from 'react';

import { QRCodeCanvas } from 'qrcode.react';

import { getDomain } from '@helpers/domain.helper';
import { showModal } from '@ui-kit/Modal';

import { IObstacle } from '../../@types/obstacles.types';

interface IObstacleQRModalProps {
  data: IObstacle;
}

const ObstacleQRModal: React.FC<IObstacleQRModalProps> = ({ data }) => {
  const url = new URL(`obstacles/code/${data.code}`, `https://${getDomain()}`);

  url.searchParams.set('t', data.type);

  return (
    <div>
      <QRCodeCanvas value={url.href} width={200} height={200} />
      <br />
      <code>{url.href}</code>
    </div>
  );
};

export const showObstacleQrModal = (data: IObstacle) => {
  showModal({
    title: data.name,
    size: 'lg',
    children: () => <ObstacleQRModal data={data} />,
  });
};

export default ObstacleQRModal;
